screens.prose:
A **constructor** runs when an object is created; a **destructor**, `~Position`, runs when it ends. Python frees an object some time after the last name lets go. C++ is exact.

```cpp
struct Position {
    std::string sym;
    Position(std::string s) : sym(s) { std::cout << "open " << sym << "\n"; }
    ~Position() { std::cout << "close " << sym << "\n"; }
};
void trade() {
    Position p("VOD");
    std::cout << "trading\n";
}
int main() {
    trade();
    std::cout << "done\n";
}
```

widget.prelude:
#include <vector>
// book.h, included for you. Book::live counts Books that exist.
struct Book {
    static inline int live = 0;
    double sum = 0;
    Book() { ++live; }
    ~Book() { --live; }
    void add(double x) { sum += x; }
    double total() const { return sum; }
};

widget.starter:
#include <memory>
#include <vector>

double net_exposure(const std::vector<double>& qty, const std::vector<double>& px, double limit) {
    Book* book = new Book;
    for (std::size_t i = 0; i < qty.size(); ++i)
        book->add(qty[i] * px[i]);
    if (book->total() > limit) return limit;
    double t = book->total();
    delete book;
    return t;
}

widget.solution:
#include <memory>
#include <vector>

double net_exposure(const std::vector<double>& qty, const std::vector<double>& px, double limit) {
    auto book = std::make_unique<Book>();
    for (std::size_t i = 0; i < qty.size(); ++i)
        book->add(qty[i] * px[i]);
    if (book->total() > limit) return limit;
    return book->total();
}

screens.prose:
A `unique_ptr` is the *only* owner, so copying one is a compile error. `std::move(a)` hands ownership over instead, and leaves `a` empty.

```cpp
void book_order(std::unique_ptr<Order> o);

auto a = std::make_unique<Order>(Order{100});
book_order(a);
```

